/** Retire identifiers generated by the former web PUSH placeholder.
 * A browser UUID is not an FCM registration token. Never generate or register one.
 * Keep failed legacy cleanup retryable at the next verified session.
 */
const LEGACY_KEYS = ['d360_device_token', 'd360_registered_device_token'];
const inFlight = new Map<string, Promise<void>>();
const TIMEOUT_MS = 1500;

export async function retireLegacyPushDevice(accessToken: string | null): Promise<void> {
  if (typeof window === 'undefined' || !accessToken) return;
  try {
    const tokens = new Set(
      LEGACY_KEYS.map((key) => localStorage.getItem(key)).filter(
        (token): token is string =>
          !!token && /^web-[A-Za-z0-9-]+$/.test(token) && token.length >= 8 && token.length <= 255
      )
    );
    await Promise.all(
      Array.from(tokens, (token) => {
        const key = JSON.stringify([accessToken, token]);
        const existing = inFlight.get(key);
        if (existing) return existing;
        const work = (async () => {
          const controller = new AbortController();
          const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
          try {
            const base = (
              process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000/api/v1'
            ).replace(/\/$/, '');
            const response = await fetch(`${base}/notifications/unregister-device`, {
              method: 'DELETE',
              headers: {
                'Content-Type': 'application/json',
                Authorization: `Bearer ${accessToken}`,
              },
              body: JSON.stringify({ device_token: token }),
              signal: controller.signal,
              keepalive: true,
            });
            if (response.ok) {
              for (const storageKey of LEGACY_KEYS) {
                if (localStorage.getItem(storageKey) === token) localStorage.removeItem(storageKey);
              }
            }
          } catch {
            // No private provider, token, or network diagnostics in browser logs.
          } finally {
            clearTimeout(timer);
          }
        })();
        inFlight.set(key, work);
        return work.finally(() => {
          if (inFlight.get(key) === work) inFlight.delete(key);
        });
      })
    );
  } catch {
    // Storage denial or cleanup failure must never prevent local logout/login.
  }
}
